WITH cleaned AS (SELECT *, CEIL(budget) AS budget_whole FROM departments WHERE dept_name IS NOT NULL) SELECT id, dept_name, location, budget, budget_whole, SUM(budget_whole) OVER w_part AS running_budget_whole, LEAD(budget, 1) OVER (PARTITION BY location, dept_name ORDER BY budget_whole, id) AS next_budget, NTILE(3) OVER (PARTITION BY dept_name ORDER BY budget_whole, id) AS budget_whole_bucket, CUME_DIST() OVER w_part_2 AS budget_cume_dist FROM cleaned WINDOW w_part AS (ORDER BY budget_whole, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW), w_part_2 AS (PARTITION BY dept_name, location ORDER BY budget);
